#include <type_traits>
#include <string>

// Function template that only compiles for T with operator+= that returns T&.
// For std::string this works; for an int it works; for a custom no-op type
// without += it's a hard error (no fallback specialisation provided).
template<typename T,
         typename = std::enable_if_t<std::is_default_constructible_v<T>>>
T concat_three(const T& a, const T& b, const T& c) {
    T result{};
    result += a;
    result += b;
    result += c;
    return result;
}

// Usage that exposes the SFINAE constraint:
void use_three() {
    auto s = concat_three<std::string>("a", "b", "c");  // OK
    auto i = concat_three<int>(1, 2, 3);                  // OK
    // auto v = concat_three<void>();                     // hard error
}
